insert into public.arena_scenarios(id,course_id,slug,title,hook,context,tier,concept_ids,estimated_minutes,status,solution_brief) values('system-design:limited-stock-checkout','system-design','limited-stock-checkout','Who gets the last packets?','There are 340 packets of Maggi and 200,000 people adding them to cart. Where does the system make the stock promise?','Flash sale checkout with a single limited SKU','intermediate',array['system-design:inventory-reservation','system-design:atomic-stock']::text[],7,'live','Cart shows an estimate, not a promise. At Place order, atomically reserve one unit with a short expiry. The checkout path owns the critical counter; expired reservations return stock, and confirmed payment commits the order idempotently.') on conflict(id) do update set title=excluded.title,hook=excluded.hook,context=excluded.context,tier=excluded.tier,concept_ids=excluded.concept_ids,estimated_minutes=excluded.estimated_minutes,status=excluded.status,solution_brief=excluded.solution_brief;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:limited-stock-checkout:1','system-design:limited-stock-checkout',1,'initial','design_choice','What does Add to cart mean for stock?',null,'[{"id":"a","text":"A best-effort availability hint, without reservation"},{"id":"b","text":"A permanent reservation until the browser closes"},{"id":"c","text":"An immediate purchase"}]'::jsonb,'a','A avoids trapping 340 units in abandoned carts. B can strand every unit. C charges or commits before checkout consent.','A cart is intent; it is not yet a stock guarantee.',array['system-design:inventory-reservation']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:limited-stock-checkout:2','system-design:limited-stock-checkout',2,'probe','design_choice','Two buyers click Place order for the final packet. How is one winner chosen?','Only one unreserved packet remains.','[{"id":"a","text":"One conditional atomic decrement or reservation transaction"},{"id":"b","text":"Read stock separately, then each writes stock minus one"},{"id":"c","text":"Have both browsers hide the button"}]'::jsonb,'a','A serializes the last-unit claim. B lets both see one and oversell. C is cosmetic and cannot arbitrate races across devices.','The invariant is reserved plus sold never exceeds 340.',array['system-design:atomic-stock']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:limited-stock-checkout:3','system-design:limited-stock-checkout',3,'probe','tradeoff','A buyer reserves one packet but abandons payment. What prevents stock staying trapped?','Payment has not completed after the hold deadline.','[{"id":"a","text":"A short reservation expiry and idempotent release"},{"id":"b","text":"Leave it reserved forever for fairness"},{"id":"c","text":"Let another buyer spend the same reservation ID"}]'::jsonb,'a','A returns the unit after the deadline. B permanently loses stock. C creates double-spend risk and breaks ownership.','Expiry recovery must work even if the browser never returns.',array['system-design:inventory-reservation']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:limited-stock-checkout:4','system-design:limited-stock-checkout',4,'probe','tradeoff','The cache says 12 left while the durable counter says 0. What should checkout do?','Cart reads a slightly stale availability cache.','[{"id":"a","text":"Reject reservation and explain that the estimate changed"},{"id":"b","text":"Accept the cached value as final"},{"id":"c","text":"Insert a negative stock row and reconcile later"}]'::jsonb,'a','A treats the authoritative counter as the promise. B oversells. C creates a debt the seller may be unable to fulfil.','Cached availability can guide display, never authorize the last unit.',array['system-design:atomic-stock']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:limited-stock-checkout:5','system-design:limited-stock-checkout',5,'probe','design_choice','How should the UI behave as stock approaches zero?','The cart page is receiving far more traffic than checkout.','[{"id":"a","text":"Show less certain availability and confirm only after reservation"},{"id":"b","text":"Promise stock as soon as the item appears in cart"},{"id":"c","text":"Run every cart view through the critical stock transaction"}]'::jsonb,'a','A is truthful and keeps the hot counter for checkout. B promises too early. C puts 200,000 cart views on a 340-unit contention path.','Only checkout needs to contend on the critical counter.',array['system-design:inventory-reservation','system-design:atomic-stock']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenarios(id,course_id,slug,title,hook,context,tier,concept_ids,estimated_minutes,status,solution_brief) values('system-design:password-change-sessions','system-design','password-change-sessions','A password change that leaves an old phone active','You change your password, but your other phone can still like, comment and send messages. How should the service log it out?','Consumer app with three phone sessions and stateless API workers','foundations',array['system-design:session-revocation','system-design:token-validation']::text[],7,'live','Issue a separate opaque session or token identifier per device. On password change, revoke the other session IDs in an authoritative store. Check revocation on protected requests; a short cache TTL trades read load for a bounded stale window.') on conflict(id) do update set title=excluded.title,hook=excluded.hook,context=excluded.context,tier=excluded.tier,concept_ids=excluded.concept_ids,estimated_minutes=excluded.estimated_minutes,status=excluded.status,solution_brief=excluded.solution_brief;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:password-change-sessions:1','system-design:password-change-sessions',1,'initial','design_choice','Where should the server keep revocable session identity?',null,'[{"id":"a","text":"A distinct session ID per login in a server-side store"},{"id":"b","text":"Only an expiry timestamp inside each signed token"},{"id":"c","text":"The latest password hash in browser storage"}]'::jsonb,'a','A allows selective revocation. B remains valid until expiry even after a password change. C is client-controlled and cannot revoke another phone.','A signed token proves issuance, not that the session is still allowed.',array['system-design:session-revocation']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:password-change-sessions:2','system-design:password-change-sessions',2,'probe','tradeoff','The user has three phones and wants only the stolen one logged out. What changes?','One phone is reported stolen; the other two are trusted.','[{"id":"a","text":"Revoke that phone’s session ID while retaining the other two"},{"id":"b","text":"Rotate one global signing key for every user"},{"id":"c","text":"Clear the stolen phone’s local storage remotely"}]'::jsonb,'a','A targets one session. B invalidates every user and is operationally costly. C cannot reliably reach an offline or hostile device.','Revocation granularity must match the product action.',array['system-design:session-revocation']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:password-change-sessions:3','system-design:password-change-sessions',3,'probe','design_choice','At 1000 authenticated requests per second, how should workers check revocation?','Each request now needs a revocation decision.','[{"id":"a","text":"Check a short-lived shared cache backed by the authoritative session store"},{"id":"b","text":"Trust the token until its hour-long expiry"},{"id":"c","text":"Read the password table with a full scan on every request"}]'::jsonb,'a','A reduces store reads and bounds staleness by TTL. B leaves the stolen phone active for up to an hour. C makes the hot path unnecessarily expensive.','Cache expiry is part of the security promise.',array['system-design:token-validation']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:password-change-sessions:4','system-design:password-change-sessions',4,'probe','tradeoff','A cache entry lives for 30 seconds. What is the worst ordinary stale window after revocation?','The team proposes a 30-second cache TTL.','[{"id":"a","text":"About 30 seconds unless entries are actively invalidated"},{"id":"b","text":"Zero seconds because the database row is gone"},{"id":"c","text":"One hour because signed tokens cannot be checked"}]'::jsonb,'a','A follows directly from the TTL. B ignores stale cache entries. C ignores the revocation lookup; token expiry is a separate bound.','State the stale window explicitly in the design.',array['system-design:token-validation']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('system-design:password-change-sessions:5','system-design:password-change-sessions',5,'probe','design_choice','The revoke operation writes asynchronously. When may the UI say “logged out”?','Product wants a confirmation banner after the password change.','[{"id":"a","text":"After the revocation write is durable; invalidate caches if immediate effect is promised"},{"id":"b","text":"As soon as the queue accepts the job"},{"id":"c","text":"Only after the old phone reconnects and acknowledges"}]'::jsonb,'a','A ties the claim to enforcement. B can leave the old phone posting while the queue waits or fails. C gives an attacker veto power over completion.','Do not claim immediate logout before the enforcement path changes.',array['system-design:session-revocation','system-design:token-validation']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenarios(id,course_id,slug,title,hook,context,tier,concept_ids,estimated_minutes,status,solution_brief) values('dsa:autocomplete-top-five','dsa','autocomplete-top-five','Autocomplete under 50 ms','A search box needs five suggestions for each typed prefix in under 50 ms. What data structure fits?','Search suggestion service; query frequencies change throughout the day','foundations',array['dsa:trie','dsa:top-k']::text[],7,'live','Use a trie and cache top five suggestions at each prefix node for O(L + 5) query work, where L is prefix length. This spends O(5 × total indexed prefix nodes) extra references. Batch frequency updates; a full sort at query time loses the latency budget.') on conflict(id) do update set title=excluded.title,hook=excluded.hook,context=excluded.context,tier=excluded.tier,concept_ids=excluded.concept_ids,estimated_minutes=excluded.estimated_minutes,status=excluded.status,solution_brief=excluded.solution_brief;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:autocomplete-top-five:1','dsa:autocomplete-top-five',1,'initial','algo_choice','Which structure finds the prefix without scanning every query string?',null,'[{"id":"a","text":"A trie keyed by characters"},{"id":"b","text":"An unsorted array scanned linearly"},{"id":"c","text":"A stack of recent queries"}]'::jsonb,'a','A walks the prefix in L characters. B costs a scan over all N strings. C has recency order but no prefix index.','A trie indexes prefixes directly.',array['dsa:trie']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:autocomplete-top-five:2','dsa:autocomplete-top-five',2,'probe','complexity','With prefix length L, what is trie lookup time before collecting suggestions?','The trie is already built in memory.','[{"id":"a","text":"O(L)"},{"id":"b","text":"O(N)"},{"id":"c","text":"O(L log N)"}]'::jsonb,'a','A follows one edge per character. B describes a scan of all N entries. C adds a logarithmic search that a character-edge lookup does not perform.','The number of stored queries does not appear in prefix traversal time.',array['dsa:trie']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:autocomplete-top-five:3','dsa:autocomplete-top-five',3,'probe','algo_choice','How can the endpoint return top five without traversing a huge subtree per keystroke?','A popular prefix has millions of matching queries.','[{"id":"a","text":"Store a precomputed top-five list at each prefix node"},{"id":"b","text":"Sort every matching query on every request"},{"id":"c","text":"Return the first five insertion-order leaves"}]'::jsonb,'a','A makes collection bounded to five after lookup. B grows with the matching set. C does not produce the highest-frequency suggestions.','Precomputation trades memory and update work for read latency.',array['dsa:top-k']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:autocomplete-top-five:4','dsa:autocomplete-top-five',4,'probe','tradeoff','What is the main cost of caching five suggestions at each node?','The team agrees to cache top five per node.','[{"id":"a","text":"Up to five suggestion references per indexed prefix node plus update work"},{"id":"b","text":"Exactly five bytes total"},{"id":"c","text":"No update cost because the trie is immutable"}]'::jsonb,'a','A scales with nodes and changes in frequency. B ignores pointers and node count. C contradicts live frequency updates.','Measure indexed prefix nodes, not just the count of full terms.',array['dsa:top-k']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:autocomplete-top-five:5','dsa:autocomplete-top-five',5,'probe','design_choice','The query log updates every second and traffic reaches a billion daily requests. What should be separated?','Read traffic now dwarfs frequency-update traffic.','[{"id":"a","text":"Batch ranking updates from the read-serving trie and atomically publish refreshed snapshots"},{"id":"b","text":"Sort the full log for each keystroke"},{"id":"c","text":"Mutate every ancestor node synchronously inside the user request"}]'::jsonb,'a','A keeps reads predictable and permits slightly stale popularity. B scales with log volume per request. C makes user latency depend on update fan-out.','Freshness can be seconds while the 50 ms read target stays firm.',array['dsa:trie','dsa:top-k']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenarios(id,course_id,slug,title,hook,context,tier,concept_ids,estimated_minutes,status,solution_brief) values('dsa:rolling-error-window','dsa','rolling-error-window','Alert on the last five minutes','A service emits timestamped error events. An alert must show the number in the last five minutes after each new event.','Monitoring pipeline with events arriving in timestamp order','intermediate',array['dsa:sliding-window','dsa:amortized-analysis']::text[],7,'live','Keep a deque of timestamps inside the rolling interval. Append each new event and pop expired timestamps from the front. Each event is appended and removed at most once: O(1) amortized update, O(W) memory for W live events. An unsorted array scan costs O(N) per update; a heap adds O(log N) work that ordered arrivals do not need.') on conflict(id) do update set title=excluded.title,hook=excluded.hook,context=excluded.context,tier=excluded.tier,concept_ids=excluded.concept_ids,estimated_minutes=excluded.estimated_minutes,status=excluded.status,solution_brief=excluded.solution_brief;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:rolling-error-window:1','dsa:rolling-error-window',1,'initial','algo_choice','Which structure supports adding a new timestamp and evicting the oldest?',null,'[{"id":"a","text":"A deque"},{"id":"b","text":"An unsorted array with full scans"},{"id":"c","text":"A recursion stack"}]'::jsonb,'a','A supports append and front removal. B rescans history per event. C does not model a rolling window.','Ordered input lets the oldest expired event sit at the front.',array['dsa:sliding-window']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:rolling-error-window:2','dsa:rolling-error-window',2,'probe','design_choice','At timestamp t, which entries should be removed for a strict trailing 300-second interval (t-300, t]?','The monitoring contract excludes events exactly 300 seconds old.','[{"id":"a","text":"Entries with timestamp less than or equal to t-300"},{"id":"b","text":"Only the newest entry"},{"id":"c","text":"Every entry older than t"}]'::jsonb,'a','A matches the open lower bound. B keeps old events. C empties the useful window.','Boundary choice matters at exactly five minutes.',array['dsa:sliding-window']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:rolling-error-window:3','dsa:rolling-error-window',3,'probe','complexity','A burst expires many entries at once. What is amortized work per event over the stream?','The deque has already been maintained since startup.','[{"id":"a","text":"O(1)"},{"id":"b","text":"O(N)"},{"id":"c","text":"O(N log N)"}]'::jsonb,'a','A holds because each event is inserted once and removed once. B charges a full history scan to every event. C assumes sorting that ordered input avoids.','A single slow eviction does not change the total linear work.',array['dsa:amortized-analysis']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:rolling-error-window:4','dsa:rolling-error-window',4,'probe','tradeoff','What changes if events arrive out of timestamp order?','A network delay makes an older event arrive after a newer one.','[{"id":"a","text":"The front may no longer be the oldest; reorder within a bounded lateness window or use a time index"},{"id":"b","text":"Nothing; deque order is always timestamp order"},{"id":"c","text":"Discard every event until the clock catches up"}]'::jsonb,'a','A names the broken invariant and a recovery. B confuses arrival with event time. C loses valid late events.','Document whether the window uses event time or arrival time.',array['dsa:sliding-window']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('dsa:rolling-error-window:5','dsa:rolling-error-window',5,'probe','design_choice','A long quiet period follows a burst. When does the displayed count reach zero?','The UI must update while no errors arrive.','[{"id":"a","text":"On a clock tick or read that evicts expired entries, even without a new event"},{"id":"b","text":"Only when the next error arrives"},{"id":"c","text":"Never; old timestamps stay in the deque forever"}]'::jsonb,'a','A maintains a truthful live count. B displays stale alerts through quiet periods. C ignores expiry entirely.','An event-only update loop needs a timer or read-time eviction.',array['dsa:sliding-window']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenarios(id,course_id,slug,title,hook,context,tier,concept_ids,estimated_minutes,status,solution_brief) values('java:lost-counter-updates','java','lost-counter-updates','A counter loses increments','A Java service counts accepted requests. With eight worker threads, the displayed count is lower than the number of accepted requests.','Single JVM request handler with a shared metric counter','intermediate',array['java:concurrency','java:atomicity']::text[],7,'live','counter++ is read-modify-write, so concurrent increments are lost. AtomicLong.incrementAndGet provides atomic updates and visibility for this single-JVM metric. LongAdder often scales better for high contention with a non-atomic aggregate read; neither coordinates across hosts.') on conflict(id) do update set title=excluded.title,hook=excluded.hook,context=excluded.context,tier=excluded.tier,concept_ids=excluded.concept_ids,estimated_minutes=excluded.estimated_minutes,status=excluded.status,solution_brief=excluded.solution_brief;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:lost-counter-updates:1','java:lost-counter-updates',1,'initial','debug','What race exists in the code?',null,'[{"id":"a","text":"Two threads can read the same value and overwrite one another’s increment"},{"id":"b","text":"The JVM always serializes ++ on shared fields"},{"id":"c","text":"The counter overflows after eight requests"}]'::jsonb,'a','A is the lost-update race. B is false: ++ is read, add, write. C is unrelated to this small workload.','volatile alone gives visibility, not atomic read-modify-write.',array['java:concurrency']::text[],'static long count;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:lost-counter-updates:2','java:lost-counter-updates',2,'probe','predict_output','If both threads read 7 before either writes, what value can the field hold after both increments?','Both workers have already read the old value.','[{"id":"a","text":"8"},{"id":"b","text":"9"},{"id":"c","text":"14"}]'::jsonb,'a','A occurs when both write 8. B needs serialized increments. C would require adding the old values rather than one each.','The lost update is observable despite both handlers completing.',array['java:atomicity']::text[],'long count = 7;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:lost-counter-updates:3','java:lost-counter-updates',3,'probe','design_choice','Which replacement gives atomic increments and a consistent value on this JVM?','The product needs an exact count at read time.','[{"id":"a","text":"AtomicLong.incrementAndGet()"},{"id":"b","text":"volatile long with count++"},{"id":"c","text":"A plain long renamed total"}]'::jsonb,'a','A performs an atomic update. B exposes writes but still loses simultaneous increments. C changes no behavior.','Choose the primitive based on the required consistency of reads.',array['java:atomicity']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:lost-counter-updates:4','java:lost-counter-updates',4,'probe','tradeoff','Contention grows to hundreds of threads, and the dashboard tolerates a non-atomic aggregate snapshot. What may improve throughput?','The exact-read requirement has been relaxed.','[{"id":"a","text":"LongAdder, whose cells reduce contention"},{"id":"b","text":"Synchronize every unrelated request method"},{"id":"c","text":"Use a new AtomicLong in each request"}]'::jsonb,'a','A spreads increments across cells; sum is not an atomic snapshot. B broadens contention. C loses the shared total.','LongAdder trades exact point-in-time reads for scalable updates.',array['java:concurrency','java:atomicity']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:lost-counter-updates:5','java:lost-counter-updates',5,'probe','tradeoff','The service now runs on three hosts. What does AtomicLong count?','Traffic is load-balanced across three processes.','[{"id":"a","text":"Only increments in its own JVM; combine durable events or a shared counter for a global total"},{"id":"b","text":"All hosts automatically because the class is static"},{"id":"c","text":"Only requests from the first thread"}]'::jsonb,'a','A recognizes process boundaries. B confuses static per JVM with global state. C is unrelated to AtomicLong.','Thread safety does not provide distributed coordination.',array['java:concurrency']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenarios(id,course_id,slug,title,hook,context,tier,concept_ids,estimated_minutes,status,solution_brief) values('java:static-cache-leak','java','static-cache-leak','The week-old service runs out of heap','A Java service throws OutOfMemoryError after a week. Heap dumps show millions of entries in a static HashMap cache.','Production service whose cache keys are request-derived strings','foundations',array['java:gc-leaks','java:cache-bounds']::text[],7,'live','The static map retains strong references indefinitely. Use an explicit bounded cache with eviction; a LinkedHashMap access-order LRU is a small single-process option. WeakHashMap is not a size bound and fails if keys stay strongly referenced elsewhere. Confirm retained size and load behavior.') on conflict(id) do update set title=excluded.title,hook=excluded.hook,context=excluded.context,tier=excluded.tier,concept_ids=excluded.concept_ids,estimated_minutes=excluded.estimated_minutes,status=excluded.status,solution_brief=excluded.solution_brief;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:static-cache-leak:1','java:static-cache-leak',1,'initial','debug','What is the most direct root cause?',null,'[{"id":"a","text":"The static map retains entries without an eviction bound"},{"id":"b","text":"The garbage collector never scans static fields"},{"id":"c","text":"Every String key is automatically interned"}]'::jsonb,'a','A explains growing retained heap. B is false: statics are GC roots. C is not how arbitrary request strings behave.','GC cannot reclaim objects still reachable from a static map.',array['java:gc-leaks']::text[],'static final Map<String, Result> CACHE = new HashMap<>();
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:static-cache-leak:2','java:static-cache-leak',2,'probe','tradeoff','A teammate switches to WeakHashMap. What remains risky?','The team wants a one-line fix.','[{"id":"a","text":"Eviction depends on key reachability and GC timing, not a predictable capacity"},{"id":"b","text":"It guarantees at most 100 entries"},{"id":"c","text":"It makes every value weak as well as every key"}]'::jsonb,'a','A is why it is not a bounded cache. B invents a limit. C misstates WeakHashMap: values remain strong while entries exist.','Use weak keys only when key lifetime is the intended ownership rule.',array['java:gc-leaks']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:static-cache-leak:3','java:static-cache-leak',3,'probe','design_choice','Which simple standard-library strategy caps one JVM cache at 10,000 entries?','The cache does not need to be shared across hosts.','[{"id":"a","text":"Access-order LinkedHashMap with removeEldestEntry"},{"id":"b","text":"An unbounded ConcurrentHashMap"},{"id":"c","text":"A static HashMap plus System.gc() on every insert"}]'::jsonb,'a','A enforces capacity. B is thread-safe but still unbounded. C cannot collect strongly reachable entries and hurts throughput.','Bound entries and estimate bytes per value; count alone may not cap memory tightly.',array['java:cache-bounds']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:static-cache-leak:4','java:static-cache-leak',4,'probe','debug','The cache key is mutated after insertion. Why can lookup fail?','A new key object contains mutable fields.','[{"id":"a","text":"Its hashCode may change, so it is searched in the wrong bucket"},{"id":"b","text":"HashMap automatically rehashes the single entry on mutation"},{"id":"c","text":"equals is never used by HashMap"}]'::jsonb,'a','A breaks hash-based lookup. B does not happen automatically. C is false: equals resolves candidate keys after hash selection.','Use immutable keys whose equals and hashCode agree for their lifetime.',array['java:cache-bounds']::text[],'Map<Key, Result> cache = new HashMap<>();
insert into public.arena_scenario_steps(id,scenario_id,position,kind,step_type,prompt,context_note,options,correct_option_id,explanation,bottleneck_note,concept_ids,code_snippet,language) values('java:static-cache-leak:5','java:static-cache-leak',5,'probe','design_choice','How should the fix be verified under load?','The eviction policy has been deployed to staging.','[{"id":"a","text":"Track retained heap, cache entry count, hit rate and latency over a sustained test"},{"id":"b","text":"Run one request and check that it returns 200"},{"id":"c","text":"Call System.gc() and assume a smaller heap means success"}]'::jsonb,'a','A checks both memory bound and usefulness. B misses week-long growth. C is not a representative workload or correctness check.','A bounded cache that thrashes can trade the leak for latency.',array['java:gc-leaks','java:cache-bounds']::text[],null,null) on conflict(id) do update set prompt=excluded.prompt,context_note=excluded.context_note,options=excluded.options,correct_option_id=excluded.correct_option_id,explanation=excluded.explanation,bottleneck_note=excluded.bottleneck_note,concept_ids=excluded.concept_ids,code_snippet=excluded.code_snippet,language=excluded.language;
